#include "contour.h"

// Implement the contour plotting functionality in C++

// contour.h
#ifndef CONTOUR_H
#define CONTOUR_H

void contourPlot(double* data, int rows, int cols, double* x, double* y, int numLevels, double* levels);

#endif

// conrec.c
// Implement the contour plotting algorithm in C

// swig_contour.py
import numpy as np
import _swig_contour

def contour_plot(data, x, y, levels):
    data = np.asarray(data, dtype=np.float64)
    x = np.asarray(x, dtype=np.float64)
    y = np.asarray(y, dtype=np.float64)
    levels = np.asarray(levels, dtype=np.float64)
    return _swig_contour.contourPlot(data, x, y, levels)
```

